-- Generated by `npm run db:sql`. Run in Supabase → SQL Editor. Safe to run more than once.
-- PostgreSQL schema for the Aurelia directory, booking system, VIP portal and CMS. Idempotent: safe to run again (npm run db:init).
-- Runs on Supabase / any PostgreSQL, and on the embedded PGlite database used for local development.
-- Timestamps are TIMESTAMPTZ. Booking days and times are Manila wall-clock values (DATE / TIME / TIMESTAMP).

-- "Today" in the Philippines (UTC+8).
CREATE OR REPLACE FUNCTION ph_today() RETURNS date
  LANGUAGE sql STABLE AS $$ SELECT (now() AT TIME ZONE 'Asia/Manila')::date $$;
-- Current Manila wall-clock time, for "is this slot already in the past?"
CREATE OR REPLACE FUNCTION ph_now() RETURNS timestamp
  LANGUAGE sql STABLE AS $$ SELECT (now() AT TIME ZONE 'Asia/Manila') $$;

-- ---------- Site ----------
CREATE TABLE IF NOT EXISTS site_settings (
  key         VARCHAR(50) PRIMARY KEY,
  value       VARCHAR(4000) NULL,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Profile categories (Female, Male, Transgender …). Each has its own landing page.
CREATE TABLE IF NOT EXISTS categories (
  id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name              VARCHAR(60)  NOT NULL CONSTRAINT uq_categories_name UNIQUE,
  slug              VARCHAR(80)  NOT NULL CONSTRAINT uq_categories_slug UNIQUE,
  description       VARCHAR(300) NULL,
  intro             VARCHAR(1000) NULL,
  seo_title         VARCHAR(70)  NULL,
  meta_description  VARCHAR(170) NULL,
  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order        INT NOT NULL DEFAULT 0,
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Cities (parent_id NULL) and the service areas inside them. Each published one has a landing page.
CREATE TABLE IF NOT EXISTS locations (
  id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  parent_id         INT NULL REFERENCES locations(id) ON DELETE RESTRICT,
  name              VARCHAR(100) NOT NULL,
  slug              VARCHAR(120) NOT NULL CONSTRAINT uq_locations_slug UNIQUE,
  region            VARCHAR(100) NULL,
  intro             VARCHAR(600) NULL,
  sections          TEXT NOT NULL DEFAULT '[]',           -- landing page body, same format as content pages
  image_url         VARCHAR(500) NULL,
  image_file        VARCHAR(300) NULL,
  image_alt         VARCHAR(200) NULL,
  seo_title         VARCHAR(70)  NULL,
  meta_description  VARCHAR(170) NULL,
  is_popular        BOOLEAN NOT NULL DEFAULT FALSE,       -- shown under "Popular locations" on the homepage
  is_published      BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order        INT NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE INDEX IF NOT EXISTS ix_locations_parent ON locations(parent_id, sort_order);

-- ---------- VIP membership tiers ----------
-- rank orders the tiers: a member of rank 3 can see everything open to rank 1–3.
CREATE TABLE IF NOT EXISTS tiers (
  id             INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name           VARCHAR(60)  NOT NULL CONSTRAINT uq_tiers_name UNIQUE,
  slug           VARCHAR(80)  NOT NULL CONSTRAINT uq_tiers_slug UNIQUE,
  rank           SMALLINT     NOT NULL DEFAULT 1 CHECK (rank BETWEEN 1 AND 20),
  description    VARCHAR(500) NULL,
  price          NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (price >= 0),
  duration_days  INT NOT NULL DEFAULT 30 CHECK (duration_days BETWEEN 1 AND 3660),
  perks          TEXT NOT NULL DEFAULT '[]',              -- JSON list of strings
  color          VARCHAR(7)   NULL,
  is_public      BOOLEAN NOT NULL DEFAULT TRUE,           -- listed on the VIP page
  is_active      BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order     INT NOT NULL DEFAULT 0,
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------- Profiles ----------
CREATE TABLE IF NOT EXISTS profiles (
  id                  INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug                VARCHAR(120) NOT NULL CONSTRAINT uq_profiles_slug UNIQUE,
  display_name        VARCHAR(80)  NOT NULL,
  category_id         INT NOT NULL REFERENCES categories(id),
  base_location_id    INT NULL REFERENCES locations(id) ON DELETE SET NULL,
  age                 SMALLINT NOT NULL CHECK (age BETWEEN 18 AND 99),   -- adults only
  tagline             VARCHAR(160) NULL,
  bio                 TEXT NULL,
  languages           VARCHAR(200) NULL,                 -- comma separated
  nationality         VARCHAR(60)  NULL,
  height_cm           SMALLINT NULL CHECK (height_cm IS NULL OR height_cm BETWEEN 120 AND 230),
  attributes          TEXT NOT NULL DEFAULT '[]',        -- JSON [{ label, value }] shown as a fact list
  status              VARCHAR(12) NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft','Published','Hidden','Retired')),
  is_featured         BOOLEAN NOT NULL DEFAULT FALSE,
  is_verified         BOOLEAN NOT NULL DEFAULT FALSE,     -- "Verified" badge: photos and identity checked by staff
  verified_at         TIMESTAMPTZ NULL,
  age_verified_at     TIMESTAMPTZ NULL,                  -- government ID checked (18+); required before publishing
  verification_notes  VARCHAR(1000) NULL,                -- staff only
  vip_tier_id         INT NULL REFERENCES tiers(id) ON DELETE SET NULL, -- only members of this tier or higher see the profile
  booking_enabled     BOOLEAN NOT NULL DEFAULT TRUE,
  away_until          DATE NULL,                         -- temporarily unavailable until this day (inclusive)
  away_note           VARCHAR(200) NULL,
  last_active_at      TIMESTAMPTZ NULL,                  -- "recently active" sort
  published_at        TIMESTAMPTZ NULL,
  retired_at          TIMESTAMPTZ NULL,
  seo_title           VARCHAR(70)  NULL,
  meta_description    VARCHAR(170) NULL,
  staff_notes         TEXT NULL,
  sort_order          INT NOT NULL DEFAULT 0,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (status <> 'Published' OR age_verified_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS ix_profiles_status ON profiles(status, category_id);
CREATE INDEX IF NOT EXISTS ix_profiles_location ON profiles(base_location_id);

-- Service areas a profile covers (cities or areas), besides the base location.
CREATE TABLE IF NOT EXISTS profile_areas (
  profile_id   INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  location_id  INT NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
  PRIMARY KEY (profile_id, location_id)
);
CREATE INDEX IF NOT EXISTS ix_profile_areas_location ON profile_areas(location_id);

-- Photos (uploaded) and videos (link to an MP4 / YouTube / Vimeo). vip_only media is sent only to qualifying members.
CREATE TABLE IF NOT EXISTS profile_media (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_id  INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  kind        VARCHAR(10) NOT NULL DEFAULT 'photo' CHECK (kind IN ('photo','video')),
  url         VARCHAR(500) NOT NULL,
  file_name   VARCHAR(300) NULL,
  poster_url  VARCHAR(500) NULL,
  alt_text    VARCHAR(200) NULL,
  is_primary  BOOLEAN NOT NULL DEFAULT FALSE,
  vip_only    BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order  INT NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_profile_media_profile ON profile_media(profile_id, sort_order);

-- Published rates: one row per session length.
CREATE TABLE IF NOT EXISTS profile_rates (
  id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_id        INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  label             VARCHAR(80) NOT NULL,
  duration_minutes  INT NOT NULL CHECK (duration_minutes BETWEEN 15 AND 1440),
  price             NUMERIC(12,2) NOT NULL CHECK (price >= 0),
  notes             VARCHAR(200) NULL,
  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order        INT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS ix_profile_rates_profile ON profile_rates(profile_id, sort_order);

-- Weekly availability. end_time may be 24:00 for "until midnight".
CREATE TABLE IF NOT EXISTS profile_schedules (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_id  INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  weekday     SMALLINT NOT NULL CHECK (weekday BETWEEN 0 AND 6),
  start_time  TIME NOT NULL,
  end_time    TIME NOT NULL,
  CHECK (end_time > start_time)
);
CREATE INDEX IF NOT EXISTS ix_profile_schedules ON profile_schedules(profile_id, weekday);

-- Days off (inclusive range).
CREATE TABLE IF NOT EXISTS profile_time_off (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_id  INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  start_date  DATE NOT NULL,
  end_date    DATE NOT NULL,
  note        VARCHAR(200) NULL,
  CHECK (end_date >= start_date)
);
CREATE INDEX IF NOT EXISTS ix_profile_time_off ON profile_time_off(profile_id, end_date);

-- Fees shown before a booking is confirmed (e.g. booking fee, travel fee for a city).
CREATE TABLE IF NOT EXISTS fees (
  id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name         VARCHAR(80) NOT NULL,
  description  VARCHAR(300) NULL,
  fee_type     VARCHAR(10) NOT NULL DEFAULT 'fixed' CHECK (fee_type IN ('fixed','percent')),
  amount       NUMERIC(12,2) NOT NULL CHECK (amount >= 0),
  location_id  INT NULL REFERENCES locations(id) ON DELETE CASCADE, -- NULL = every booking
  is_active    BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order   INT NOT NULL DEFAULT 0,
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------- Members (VIP portal) ----------
CREATE TABLE IF NOT EXISTS members (
  id                     INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  member_no              VARCHAR(20) NOT NULL CONSTRAINT uq_members_member_no UNIQUE,
  first_name             VARCHAR(80) NOT NULL,
  last_name              VARCHAR(80) NOT NULL,
  full_name              VARCHAR(170) GENERATED ALWAYS AS (first_name || ' ' || last_name) STORED,
  email                  VARCHAR(254) NOT NULL,
  phone                  VARCHAR(30) NULL,
  birthdate              DATE NULL,
  status                 VARCHAR(12) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Suspended')),
  tier_id                INT NULL REFERENCES tiers(id) ON DELETE SET NULL,
  membership_expires_on  DATE NULL,                    -- tier access ends after this day
  marketing_opt_in       BOOLEAN NOT NULL DEFAULT FALSE,
  terms_accepted_at      TIMESTAMPTZ NULL,
  notes                  TEXT NULL,                    -- staff only
  password_hash          VARCHAR(200) NULL,
  email_verified_at      TIMESTAMPTZ NULL,
  last_login_at          TIMESTAMPTZ NULL,
  created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at             TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_members_email ON members(lower(email));

CREATE TABLE IF NOT EXISTS member_sessions (
  id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  member_id     INT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
  token_hash    CHAR(64) NOT NULL CONSTRAINT uq_member_sessions_token UNIQUE,
  user_agent    VARCHAR(200) NULL,
  ip_address    VARCHAR(64) NULL,
  expires_at    TIMESTAMPTZ NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_member_sessions_member ON member_sessions(member_id);

-- One-time email links. verify: pending sign-up (data holds the details + password hash); reset: new password.
CREATE TABLE IF NOT EXISTS member_tokens (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purpose     VARCHAR(10) NOT NULL CHECK (purpose IN ('verify','reset')),
  email       VARCHAR(254) NOT NULL,
  member_id   INT NULL REFERENCES members(id) ON DELETE CASCADE,
  data        TEXT NULL,
  token_hash  CHAR(64) NOT NULL CONSTRAINT uq_member_tokens_token UNIQUE,
  expires_at  TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_member_tokens_email ON member_tokens(purpose, email);

-- Two-step sign-in with an authenticator app (TOTP). Added as ALTERs so existing databases pick them up on db:init.
ALTER TABLE members ADD COLUMN IF NOT EXISTS totp_secret         VARCHAR(64) NULL;  -- base32; set once the first code is confirmed
ALTER TABLE members ADD COLUMN IF NOT EXISTS totp_pending_secret VARCHAR(64) NULL;  -- during setup, before it's confirmed
ALTER TABLE members ADD COLUMN IF NOT EXISTS totp_enabled_at     TIMESTAMPTZ NULL;
ALTER TABLE members ADD COLUMN IF NOT EXISTS totp_last_step      BIGINT NULL;       -- last accepted 30-second step (no code reuse)
ALTER TABLE members ADD COLUMN IF NOT EXISTS totp_backup_codes   TEXT NULL;         -- JSON array of SHA-256 hashes of unused backup codes

-- A password that was correct, waiting for the authenticator code (10 minutes, 5 tries).
CREATE TABLE IF NOT EXISTS member_mfa_challenges (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  member_id   INT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
  token_hash  CHAR(64) NOT NULL CONSTRAINT uq_member_mfa_challenges_token UNIQUE,
  remember    BOOLEAN NOT NULL DEFAULT TRUE,
  attempts    INT NOT NULL DEFAULT 0,
  expires_at  TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------- Companion portal ----------
-- One sign-in per profile. Staff invite the companion by email; the account is Invited until they choose a password.
CREATE TABLE IF NOT EXISTS companion_accounts (
  id                   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_id           INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE CONSTRAINT uq_companion_accounts_profile UNIQUE,
  email                VARCHAR(254) NOT NULL,
  status               VARCHAR(12) NOT NULL DEFAULT 'Invited' CHECK (status IN ('Invited','Active','Suspended')),
  password_hash        VARCHAR(200) NULL,
  invited_by           VARCHAR(150) NULL,
  invited_at           TIMESTAMPTZ NULL,
  activated_at         TIMESTAMPTZ NULL,
  last_login_at        TIMESTAMPTZ NULL,
  totp_secret          VARCHAR(64) NULL,
  totp_pending_secret  VARCHAR(64) NULL,
  totp_enabled_at      TIMESTAMPTZ NULL,
  totp_last_step       BIGINT NULL,
  totp_backup_codes    TEXT NULL,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_companion_accounts_email ON companion_accounts(lower(email));

CREATE TABLE IF NOT EXISTS companion_sessions (
  id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id    INT NOT NULL REFERENCES companion_accounts(id) ON DELETE CASCADE,
  token_hash    CHAR(64) NOT NULL CONSTRAINT uq_companion_sessions_token UNIQUE,
  user_agent    VARCHAR(200) NULL,
  ip_address    VARCHAR(64) NULL,
  expires_at    TIMESTAMPTZ NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_companion_sessions_account ON companion_sessions(account_id);

-- Invitation and password-reset links (only the SHA-256 is stored).
CREATE TABLE IF NOT EXISTS companion_tokens (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purpose     VARCHAR(10) NOT NULL CHECK (purpose IN ('invite','reset')),
  account_id  INT NOT NULL REFERENCES companion_accounts(id) ON DELETE CASCADE,
  token_hash  CHAR(64) NOT NULL CONSTRAINT uq_companion_tokens_token UNIQUE,
  expires_at  TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS companion_mfa_challenges (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id  INT NOT NULL REFERENCES companion_accounts(id) ON DELETE CASCADE,
  token_hash  CHAR(64) NOT NULL CONSTRAINT uq_companion_mfa_challenges_token UNIQUE,
  remember    BOOLEAN NOT NULL DEFAULT TRUE,
  attempts    INT NOT NULL DEFAULT 0,
  expires_at  TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Profile updates sent from the portal, waiting for staff: new wording (kind 'details', data = JSON of the
-- proposed fields) or a new photo (kind 'photo', stored under profiles/<id>/pending until approved).
CREATE TABLE IF NOT EXISTS profile_change_requests (
  id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_id   INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  kind         VARCHAR(10) NOT NULL CHECK (kind IN ('details','photo')),
  data         TEXT NULL,
  photo_url    VARCHAR(500) NULL,
  file_name    VARCHAR(300) NULL,
  status       VARCHAR(12) NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Approved','Rejected','Withdrawn')),
  staff_note   VARCHAR(500) NULL,
  decided_by   VARCHAR(150) NULL,
  decided_at   TIMESTAMPTZ NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_profile_change_requests ON profile_change_requests(status, profile_id);

-- Membership history: requests from the portal (Pending) and what staff approved.
CREATE TABLE IF NOT EXISTS memberships (
  id                 INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  membership_no      VARCHAR(24) NOT NULL CONSTRAINT uq_memberships_membership_no UNIQUE,
  member_id          INT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
  tier_id            INT NOT NULL REFERENCES tiers(id),
  kind               VARCHAR(10) NOT NULL DEFAULT 'New' CHECK (kind IN ('New','Renewal','Upgrade','Manual')),
  status             VARCHAR(12) NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Active','Expired','Rejected','Cancelled')),
  starts_on          DATE NULL,
  ends_on            DATE NULL,
  amount             NUMERIC(12,2) NOT NULL DEFAULT 0,
  payment_method     VARCHAR(40) NULL,
  payment_reference  VARCHAR(80) NULL,
  member_note        VARCHAR(500) NULL,
  staff_note         VARCHAR(500) NULL,
  decided_by         VARCHAR(150) NULL,
  decided_at         TIMESTAMPTZ NULL,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_memberships_member ON memberships(member_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_memberships_status ON memberships(status);

CREATE TABLE IF NOT EXISTS member_favorites (
  member_id   INT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
  profile_id  INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (member_id, profile_id)
);

-- VIP collections: curated lists of profiles for members (of a minimum tier).
CREATE TABLE IF NOT EXISTS collections (
  id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title         VARCHAR(120) NOT NULL,
  slug          VARCHAR(140) NOT NULL CONSTRAINT uq_collections_slug UNIQUE,
  description   VARCHAR(600) NULL,
  min_tier_id   INT NULL REFERENCES tiers(id) ON DELETE SET NULL, -- NULL = any member with an active tier
  is_published  BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order    INT NOT NULL DEFAULT 0,
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS collection_profiles (
  collection_id  INT NOT NULL REFERENCES collections(id) ON DELETE CASCADE,
  profile_id     INT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  sort_order     INT NOT NULL DEFAULT 0,
  PRIMARY KEY (collection_id, profile_id)
);

-- ---------- Bookings and inquiries ----------
-- kind Booking: a date/time request for a published rate. kind Inquiry: a question about a profile (date optional).
CREATE TABLE IF NOT EXISTS bookings (
  id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reference         VARCHAR(24) NOT NULL CONSTRAINT uq_bookings_reference UNIQUE,
  kind              VARCHAR(10) NOT NULL DEFAULT 'Booking' CHECK (kind IN ('Booking','Inquiry')),
  profile_id        INT NOT NULL REFERENCES profiles(id),
  rate_id           INT NULL REFERENCES profile_rates(id) ON DELETE SET NULL,
  rate_label        VARCHAR(80) NULL,
  duration_minutes  INT NULL,
  booking_date      DATE NULL,
  start_time        TIME NULL,
  starts_at         TIMESTAMP NULL,                    -- Manila wall clock
  ends_at           TIMESTAMP NULL,
  location_id       INT NULL REFERENCES locations(id) ON DELETE SET NULL,
  meeting_place     VARCHAR(200) NULL,
  member_id         INT NULL REFERENCES members(id) ON DELETE SET NULL,
  client_name       VARCHAR(150) NOT NULL,
  client_email      VARCHAR(254) NOT NULL,
  client_phone      VARCHAR(30) NULL,
  preferred_contact VARCHAR(20) NULL,
  client_notes      TEXT NULL,
  rate_price        NUMERIC(12,2) NOT NULL DEFAULT 0,
  fees              TEXT NOT NULL DEFAULT '[]',        -- JSON [{ name, amount }] as quoted to the client
  fees_total        NUMERIC(12,2) NOT NULL DEFAULT 0,
  total             NUMERIC(12,2) NOT NULL DEFAULT 0,
  status            VARCHAR(12) NOT NULL DEFAULT 'Pending'
                    CHECK (status IN ('Pending','Confirmed','Completed','Cancelled','Declined','No-Show','Answered','Closed')),
  cancel_reason     VARCHAR(300) NULL,
  cancelled_by      VARCHAR(10) NULL,
  reschedule_count  SMALLINT NOT NULL DEFAULT 0,
  source            VARCHAR(12) NOT NULL DEFAULT 'Online' CHECK (source IN ('Online','Phone','Messaging','Staff')),
  staff_notes       TEXT NULL,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (kind = 'Inquiry' OR (booking_date IS NOT NULL AND starts_at IS NOT NULL AND ends_at IS NOT NULL)),
  CHECK (ends_at IS NULL OR ends_at > starts_at)
);
CREATE INDEX IF NOT EXISTS ix_bookings_profile_time ON bookings(profile_id, starts_at);
CREATE INDEX IF NOT EXISTS ix_bookings_status ON bookings(status, created_at);
CREATE INDEX IF NOT EXISTS ix_bookings_date ON bookings(booking_date);
CREATE INDEX IF NOT EXISTS ix_bookings_member ON bookings(member_id);

-- Status history; client-visible entries appear on the booking status page.
CREATE TABLE IF NOT EXISTS booking_events (
  id                 INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id         INT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  status             VARCHAR(12) NULL,
  title              VARCHAR(150) NOT NULL,
  note               VARCHAR(1000) NULL,
  actor              VARCHAR(150) NULL,
  visible_to_client  BOOLEAN NOT NULL DEFAULT TRUE,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_booking_events_booking ON booking_events(booking_id, created_at);

-- Chat between the client and the companion once a booking is confirmed. Staff read every thread in the CMS
-- and can write as the concierge. Each side's last-read message id drives unread counts and "new message" emails.
CREATE TABLE IF NOT EXISTS booking_messages (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id  INT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  sender      VARCHAR(10) NOT NULL CHECK (sender IN ('Client','Companion','Concierge')),
  author      VARCHAR(150) NULL,                 -- staff name for concierge messages
  body        VARCHAR(2000) NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_booking_messages_booking ON booking_messages(booking_id, id);
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS client_seen_message_id    INT NOT NULL DEFAULT 0;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS companion_seen_message_id INT NOT NULL DEFAULT 0;

-- ---------- Content ----------
CREATE TABLE IF NOT EXISTS content_pages (
  id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug              VARCHAR(100) NOT NULL CONSTRAINT uq_content_pages_slug UNIQUE,
  title             VARCHAR(150) NOT NULL,
  kicker            VARCHAR(60) NULL,
  intro             VARCHAR(600) NULL,
  sections          TEXT NOT NULL DEFAULT '[]',
  seo_title         VARCHAR(70)  NULL,
  meta_description  VARCHAR(170) NULL,
  show_in_footer    BOOLEAN NOT NULL DEFAULT TRUE,
  is_published      BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order        INT NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Guides, announcements and member news. audience Members (+ min tier) = exclusive content.
CREATE TABLE IF NOT EXISTS posts (
  id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug              VARCHAR(140) NOT NULL CONSTRAINT uq_posts_slug UNIQUE,
  kind              VARCHAR(14) NOT NULL DEFAULT 'Guide' CHECK (kind IN ('Guide','Announcement','News')),
  title             VARCHAR(150) NOT NULL,
  excerpt           VARCHAR(400) NULL,
  sections          TEXT NOT NULL DEFAULT '[]',
  cover_url         VARCHAR(500) NULL,
  cover_file        VARCHAR(300) NULL,
  cover_alt         VARCHAR(200) NULL,
  audience          VARCHAR(10) NOT NULL DEFAULT 'Public' CHECK (audience IN ('Public','Members')),
  min_tier_id       INT NULL REFERENCES tiers(id) ON DELETE SET NULL,
  location_id       INT NULL REFERENCES locations(id) ON DELETE SET NULL,
  is_pinned         BOOLEAN NOT NULL DEFAULT FALSE,
  is_published      BOOLEAN NOT NULL DEFAULT FALSE,
  published_at      TIMESTAMPTZ NULL,
  seo_title         VARCHAR(70)  NULL,
  meta_description  VARCHAR(170) NULL,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_posts_published ON posts(is_published, published_at DESC);

CREATE TABLE IF NOT EXISTS faqs (
  id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  group_name    VARCHAR(80) NOT NULL,
  question      VARCHAR(300) NOT NULL,
  answer        TEXT NOT NULL,
  show_on_home  BOOLEAN NOT NULL DEFAULT FALSE,
  is_published  BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order    INT NOT NULL DEFAULT 0,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Old URL → new URL. The website follows them, and retired profiles can point somewhere useful.
CREATE TABLE IF NOT EXISTS redirects (
  id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  from_path    VARCHAR(300) NOT NULL CONSTRAINT uq_redirects_from_path UNIQUE,
  to_path      VARCHAR(300) NOT NULL,
  status_code  SMALLINT NOT NULL DEFAULT 301 CHECK (status_code IN (301, 302)),
  note         VARCHAR(200) NULL,
  hits         INT NOT NULL DEFAULT 0,
  last_hit_at  TIMESTAMPTZ NULL,
  is_active    BOOLEAN NOT NULL DEFAULT TRUE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (from_path <> to_path)
);

-- Contact-form messages.
CREATE TABLE IF NOT EXISTS inquiries (
  id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reference    VARCHAR(24) NOT NULL CONSTRAINT uq_inquiries_reference UNIQUE,
  member_id    INT NULL REFERENCES members(id) ON DELETE SET NULL,
  full_name    VARCHAR(150) NOT NULL,
  email        VARCHAR(254) NOT NULL,
  phone        VARCHAR(30) NULL,
  subject      VARCHAR(50) NOT NULL,
  message      TEXT NOT NULL,
  status       VARCHAR(20) NOT NULL DEFAULT 'New' CHECK (status IN ('New','In Progress','Resolved','Closed')),
  staff_notes  TEXT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_inquiries_status ON inquiries(status, created_at);

-- ---------- Staff ----------
CREATE TABLE IF NOT EXISTS admin_roles (
  id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name         VARCHAR(60) NOT NULL CONSTRAINT uq_admin_roles_name UNIQUE,
  description  VARCHAR(250) NULL,
  permissions  TEXT NOT NULL DEFAULT '{}',               -- JSON { module: 'none'|'view'|'manage' }
  is_system    BOOLEAN NOT NULL DEFAULT FALSE,           -- Administrator: always full access
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS admin_users (
  id                    INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name             VARCHAR(150) NOT NULL,
  email                 VARCHAR(254) NOT NULL CONSTRAINT uq_admin_users_email UNIQUE,
  password_hash         VARCHAR(200) NOT NULL,
  role_id               INT NOT NULL REFERENCES admin_roles(id),
  status                VARCHAR(20) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Disabled')),
  must_change_password  BOOLEAN NOT NULL DEFAULT FALSE,
  last_login_at         TIMESTAMPTZ NULL,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS admin_sessions (
  id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id       INT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  token_hash    CHAR(64) NOT NULL CONSTRAINT uq_admin_sessions_token UNIQUE,
  user_agent    VARCHAR(200) NULL,
  expires_at    TIMESTAMPTZ NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_admin_sessions_user ON admin_sessions(user_id);

-- Append-only audit trail
CREATE TABLE IF NOT EXISTS audit_log (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor_type    VARCHAR(10) NOT NULL DEFAULT 'Staff' CONSTRAINT audit_log_actor_type_check CHECK (actor_type IN ('Staff','Member','Companion','Visitor','System')),
  user_id       INT NULL REFERENCES admin_users(id) ON DELETE SET NULL,
  user_name     VARCHAR(150) NULL,
  user_email    VARCHAR(254) NULL,
  action        VARCHAR(40) NOT NULL,
  module        VARCHAR(30) NOT NULL,
  entity_type   VARCHAR(40) NULL,
  entity_id     VARCHAR(60) NULL,
  entity_label  VARCHAR(200) NULL,
  summary       VARCHAR(500) NOT NULL,
  changes       TEXT NULL,
  ip_address    VARCHAR(64) NULL,
  user_agent    VARCHAR(200) NULL
);
-- Databases created before the companion portal: allow 'Companion' as an actor.
ALTER TABLE audit_log DROP CONSTRAINT IF EXISTS audit_log_actor_type_check;
ALTER TABLE audit_log ADD CONSTRAINT audit_log_actor_type_check CHECK (actor_type IN ('Staff','Member','Companion','Visitor','System'));
CREATE INDEX IF NOT EXISTS ix_audit_log_created ON audit_log(created_at DESC);
CREATE INDEX IF NOT EXISTS ix_audit_log_module ON audit_log(module, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_audit_log_entity ON audit_log(entity_type, entity_id);

-- Staff notifications (online bookings, membership requests, inquiries); read state per staff member
CREATE TABLE IF NOT EXISTS notifications (
  id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  type        VARCHAR(30) NOT NULL,
  module      VARCHAR(30) NOT NULL,
  title       VARCHAR(200) NOT NULL,
  body        VARCHAR(500) NULL,
  link        VARCHAR(200) NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_notifications_created ON notifications(created_at);

CREATE TABLE IF NOT EXISTS notification_reads (
  notification_id  INT NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,
  user_id          INT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  read_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (notification_id, user_id)
);

-- Keep these tables out of Supabase's auto-generated REST API: the CMS API is the only way in.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated';
  END IF;
END $$;

